create extension if not exists "pgcrypto";
create type public.app_role as enum("customer","seller","admin");
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,avatar_url text,role public.app_role not null default "customer",created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,created_at timestamptz not null default now());
create table public.stores(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,name text not null,slug text not null unique,description text,logo_url text,is_verified boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id) on delete cascade,category_id uuid references public.categories(id) on delete set null,name text not null,slug text not null unique,description text,price numeric(12,2) not null check(price>=0),stock integer not null default 0 check(stock>=0),image_url text,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.carts(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.cart_items(id uuid primary key default gen_random_uuid(),cart_id uuid not null references public.carts(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,quantity integer not null default 1 check(quantity>0),created_at timestamptz not null default now(),unique(cart_id,product_id));
create type public.order_status as enum("pending","confirmed","processing","shipped","delivered","cancelled");
create table public.orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete restrict,status public.order_status not null default "pending",total numeric(12,2) not null default 0 check(total>=0),shipping_name text,shipping_phone text,shipping_address text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,store_id uuid references public.stores(id) on delete set null,product_name text not null,unit_price numeric(12,2) not null,quantity integer not null check(quantity>0));
create table public.favorites(user_id uuid not null references public.profiles(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,product_id));
insert into public.categories(name,slug) values('Electronics','electronics'),('Fashion','fashion'),('Home & Living','home-living'),('Beauty & Personal Care','beauty'),('Grocery','grocery'),('Kids & Toys','kids-toys'),('Automotive','automotive'),('Tools & Hardware','tools-hardware'),('Sports & Outdoors','sports-outdoors'),('Books & Education','books-education'),('Digital Products','digital-products'),('Local & Handmade','local-handmade') on conflict(slug) do nothing;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,new.raw_user_meta_data->>'full_name');insert into public.carts(user_id) values(new.id);return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security;alter table public.categories enable row level security;alter table public.stores enable row level security;alter table public.products enable row level security;alter table public.carts enable row level security;alter table public.cart_items enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;alter table public.favorites enable row level security;
create policy "public read categories" on public.categories for select using(true);
create policy "public read active products" on public.products for select using(is_active=true);
create policy "public read stores" on public.stores for select using(true);
create policy "own profile read" on public.profiles for select using(auth.uid()=id);
create policy "own profile update" on public.profiles for update using(auth.uid()=id);
create policy "store owner manage" on public.stores for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
create policy "seller manage products" on public.products for all using(exists(select 1 from public.stores s where s.id=store_id and s.owner_id=auth.uid())) with check(exists(select 1 from public.stores s where s.id=store_id and s.owner_id=auth.uid()));
create policy "own cart" on public.carts for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own cart items" on public.cart_items for all using(exists(select 1 from public.carts c where c.id=cart_id and c.user_id=auth.uid())) with check(exists(select 1 from public.carts c where c.id=cart_id and c.user_id=auth.uid()));
create policy "own orders read" on public.orders for select using(auth.uid()=user_id);
create policy "own orders create" on public.orders for insert with check(auth.uid()=user_id);
create policy "own order items read" on public.order_items for select using(exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()));
create policy "own favorites" on public.favorites for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
grant select on public.categories,public.products,public.stores to anon;
grant select,insert,update,delete on public.profiles,public.stores,public.products,public.carts,public.cart_items,public.orders,public.order_items,public.favorites to authenticated;
